export default function ({ conference, start, end, creator, attendees }) {
  const code = conference?.conferenceId;
  if (
    !/^[a-z]{3}-[a-z]{4}-[a-z]{3}$/.test(code ?? "") ||
    !start?.dateTime ||
    !end?.dateTime ||
    !Number.isFinite(Date.parse(start.dateTime)) ||
    !Number.isFinite(Date.parse(end.dateTime))
  )
    throw Error("Timed Google Meet event required");
  return {
    filter: 'space.meeting_code = "' + code + '"',
    start: start.dateTime,
    end: end.dateTime,
    context: JSON.stringify({ creator, attendees, start }),
  };
}

