export default function ({ state, start, end }) {
  const s = Date.parse(start),
    e = Date.parse(end),
    matches = state.items.filter(
      (x) =>
        x.name &&
        x.startTime &&
        x.endTime &&
        Date.parse(x.startTime) < e &&
        Date.parse(x.endTime) > s,
    );
  if (matches.length !== 1)
    throw Error("Expected exactly one overlapping conference record; inspect calendar and Meet");
  return { record: matches[0].name };
}

