export default function ({ state }) {
  if (
    !state.items.length ||
    state.items.some((x) => x.state !== "FILE_GENERATED" || !x.docsDestination?.document)
  )
    throw Error("Transcript missing or not ready");
  return { ids: state.items.map((x) => x.docsDestination.document.replace(/^documents\//, "")) };
}

