export default function ({ ids, previous, text }) {
  const i = (previous?.i ?? -1) + 1;
  let combined = previous?.text ?? "";
  if (previous) {
    if (typeof text !== "string" || !text.trim()) throw Error("Empty transcript");
    combined += text + "\n";
  }
  return { state: { i, text: combined }, more: i < ids.length, id: ids[i] ?? "", text: combined };
}

