export default async function ({ calendarId, title, description, start, end, attendees }, ctx) {
  if (
    !title.trim() ||
    !/(?:Z|[+-]\d\d:\d\d)$/.test(start) ||
    !/(?:Z|[+-]\d\d:\d\d)$/.test(end) ||
    !Number.isFinite(Date.parse(start)) ||
    !Number.isFinite(Date.parse(end)) ||
    Date.parse(end) <= Date.parse(start) ||
    !Array.isArray(attendees) ||
    attendees.some((x) => !x.email)
  )
    throw Error("Invalid calendar event");
  const sorted = attendees.map((x) => ({
    email: x.email,
    ...(x.name ? { displayName: x.name } : {}),
  }));
  const key =
      "meeting:" +
      JSON.stringify([calendarId, title, start, end, sorted.map((x) => x.email).sort()]),
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect calendar before retry");
  if (s?.status === "done")
    return {
      key,
      skip: true,
      event: { start: { dateTime: start }, end: { dateTime: end } },
      response: s.response,
    };
  await ctx.state.set(key, { status: "pending" });
  return {
    key,
    skip: false,
    event: {
      summary: title,
      description,
      start: { dateTime: start },
      end: { dateTime: end },
      attendees: sorted,
    },
    response: "",
  };
}

